class StripeClient:
    def __init__(self, api_key: str, base_url: str = "https://api.stripe.com/v1"):
        self.api_key = api_key
        self.base_url = base_url

    def charge_customer(self, customer_id: str, amount_cents: int, currency: str = "usd"):
        response = requests.post(
            f"{self.base_url}/charges",
            auth=(self.api_key, ""),
            data={"customer": customer_id, "amount": amount_cents, "currency": currency},
        )
        response.raise_for_status()
        return response.json()
